class Solution:
    def splitString(self, s: str) -> bool:
        n = len(s)

        def isValid(splits):
            for i in range(1, len(splits)):
                if splits[i] != splits[i - 1] - 1:
                    return False
            return len(splits) > 1

        def dfs(i, splits):
            if i == n:
                return isValid(splits)
            num = 0
            for j in range(i, n):
                num = num * 10 + int(s[j])
                splits.append(num)
                if dfs(j + 1, splits):
                    return True
                splits.pop()
            return False

        return dfs(0, [])

class Solution:
    def splitString(self, s: str) -> bool:
        def dfs(index, prev):
            if index == len(s):
                return True
            num = 0
            for j in range(index, len(s)):
                num = num * 10 + int(s[j])
                if num + 1 == prev and dfs(j + 1, num):
                    return True
                if num >= prev:
                    break
            return False

        val = 0
        for i in range(len(s) - 1):
            val = val * 10 + int(s[i])
            if dfs(i + 1, val):
                return True

        return False
